/** 
 * Process mode character given state of addition/removal.
 * @param add indicates whether mode change is addition or removal
 * @param mode mode character
 * @return returns an entry that contains all parts of an individual modechange
 */
private ModeEntry process(boolean add,char mode){
    try {
        switch (mode) {
        case 'O':    return new ModeEntry(add,Mode.OWNER,this.params[this.index++]);
        case 'o':  return new ModeEntry(add,Mode.OPERATOR,this.params[this.index++]);
        case 'v':return new ModeEntry(add,Mode.VOICE,this.params[this.index++]);
        case 'l':String[] params=(add ? new String[]{this.params[this.index++]} : new String[]{});
        return new ModeEntry(add,Mode.LIMIT,params);
        default:return new ModeEntry(add,Mode.UNKNOWN,"" + mode);
        }
    } catch (ArrayIndexOutOfBoundsException e) {
        // Handle array index out of bounds case
        throw new IllegalArgumentException("Invalid mode parameter index", e);
    }
}
